head.script:

	scwin.onpageload = function() {
		var jsonData = [{col1:"0_col1",col2:"0_col2",col3:"0_col3",col4:"0_col4",col5:"0_col5",col6:"0_col6",col7:"0_col7",col8:"0_col8"}
        ,{col1:"1_col1",col2:"1_col2",col3:"1_col3",col4:"1_col4",col5:"1_col5",col6:"1_col6",col7:"1_col7",col8:"1_col8"}
        ,{col1:"2_col1",col2:"2_col2",col3:"2_col3",col4:"2_col4",col5:"2_col5",col6:"2_col6",col7:"2_col7",col8:"2_col8"}
        ,{col1:"3_col1",col2:"3_col2",col3:"3_col3",col4:"3_col4",col5:"3_col5",col6:"3_col6",col7:"3_col7",col8:"3_col8"}
        ,{col1:"4_col1",col2:"4_col2",col3:"4_col3",col4:"4_col4",col5:"4_col5",col6:"4_col6",col7:"4_col7",col8:"4_col8"}
        ,{col1:"5_col1",col2:"5_col2",col3:"5_col3",col4:"5_col4",col5:"5_col5",col6:"5_col6",col7:"5_col7",col8:"5_col8"}
        ,{col1:"6_col1",col2:"6_col2",col3:"6_col3",col4:"6_col4",col5:"6_col5",col6:"6_col6",col7:"6_col7",col8:"6_col8"}
        ,{col1:"7_col1",col2:"7_col2",col3:"7_col3",col4:"7_col4",col5:"7_col5",col6:"7_col6",col7:"7_col7",col8:"7_col8"}
        ,{col1:"8_col1",col2:"8_col2",col3:"8_col3",col4:"8_col4",col5:"8_col5",col6:"8_col6",col7:"8_col7",col8:"8_col8"}
        ,{col1:"9_col1",col2:"9_col2",col3:"9_col3",col4:"9_col4",col5:"9_col5",col6:"9_col6",col7:"9_col7",col8:"9_col8"}];
		dataList1.setJSON(jsonData);
	};

	scwin.onpageunload = function() {

	};

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#G_gridView1__col1', 'key-combo', {
			combo: 'down-arrow'
		});
	}	
	scwin.checkVal = function() {
		return WebSquare.wUnit.getJq('#gridView1_cell_1_0').hasClass('focusedTr');
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_0').click()");
		WebSquare.wUnit.addCommand("pause", "400");			

		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
